insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values (null, 'Cada perfil deve ser o negócio local mais confiável e mais fácil de escolher na sua região: informação verdadeira, completa e atual, em linguagem simples, para quem procura perto de casa. Primeiro ajudar a pessoa a decidir e a falar com o cliente; só depois vender. Tudo o que for publicado precisa ser verdade, sem exagero e sem promessa.', 'Próximo e educado, frases curtas, português do Brasil. Fala como um bom atendente local fala no balcão.', 'voce', 'nenhum', '', 'Nome do serviço real, cidade ou bairro, convite curto para ligar ou chamar no WhatsApp.', 'Preço, desconto, prazo, garantia, promessa de resultado, dados pessoais, admitir culpa, propaganda genérica.', 'Olá, {nome}! Obrigado pela avaliação. Ficamos felizes com o seu retorno e seguimos à disposição.', 'Conheça os serviços da nossa equipe em Londrina. Fale com a gente pelo telefone ou pelo WhatsApp do perfil.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'otica-av-rio-de-janeiro'), 'Ótica de bairro com atendimento próximo: a pessoa sai sabendo escolher bem a armação e a lente. Mostrar o que a unidade faz (óculos de grau e de sol, lentes de contato, ajustes e consertos) e facilitar a visita ou o contato pelo WhatsApp.', 'Acolhedor e familiar, como quem atende a mesma vizinhança há anos. Explica sem termos técnicos e sem pressa.', 'voce', 'nenhum', 'Equipe Óticas Gouveia', 'óculos de grau, óculos de sol, lentes de contato, armações, ajuste e conserto, atendimento da equipe, Londrina, unidade Av. Rio de Janeiro', 'preço, parcelamento, promoção, prazo de entrega, garantia, orientação de saúde visual, comparação com concorrentes', 'Olá, {nome}! Obrigado pela avaliação. Ficamos felizes que tenha gostado do atendimento na unidade Av. Rio de Janeiro. Quando precisar de óculos de grau, de sol ou lentes de contato, é só passar por aqui ou chamar no WhatsApp.', 'Precisa de óculos novos? Na Ótica Gouveia, unidade Av. Rio de Janeiro, em Londrina, nossa equipe ajuda você a escolher a armação certa para o seu dia a dia. Passe por aqui ou chame no WhatsApp.', 'automatica', false) on conflict do nothing;
