insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'clinica-central-norte'), 'Clínica odontológica da Zona Norte de Londrina que explica com clareza e cuida com atenção. Informação geral e responsável: quem indica o tratamento é o dentista, na avaliação.', 'Profissional, calmo e cuidadoso. Linguagem simples, sem jargão e sem alarmar.', 'voce', 'nenhum', 'Clínica Dentária Central Norte', 'avaliação odontológica, cuidado com a saúde bucal, Zona Norte de Londrina, agendar pelo telefone do perfil', 'promessa de resultado, antes e depois, preço, nome de profissional ou de paciente, dado de saúde, endereço (há dois no perfil), tratamento citado como garantia', 'Olá, {nome}! Agradecemos a sua avaliação e a confiança na Clínica Dentária Central Norte. Seguimos à disposição na Zona Norte de Londrina. Para agendar uma avaliação, ligue para o telefone do perfil.', 'Cuidar do sorriso começa por uma boa avaliação. Na Clínica Dentária Central Norte, na Zona Norte de Londrina, a equipe explica cada etapa com calma. Ligue e agende.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'dra-ana-luiza'), 'Consultório de odontologia na Gleba Palhano, em Londrina, com atendimento individual e atenção ao detalhe. Texto informativo, sem promessa de resultado.', 'Elegante, discreto e acolhedor. Frases curtas, sem exagero.', 'voce', 'nenhum', 'Dra. Ana Luiza Gonçalves', 'consultório, Gleba Palhano, Londrina, serviços de forma geral (limpeza, clareamento, restaurações), agendamento pelo telefone do perfil', 'promessa de resultado, antes e depois, dado de saúde, tratamento do paciente, preço, comparação com outros consultórios', 'Olá, {nome}! Obrigada pela avaliação e pela confiança. Foi um prazer receber você no consultório da Gleba Palhano. Seguimos à disposição para cuidar do seu sorriso.', 'Uma boa rotina de cuidados começa com uma avaliação. No consultório da Dra. Ana Luiza Gonçalves, na Gleba Palhano, em Londrina, você é atendido com atenção e calma. Agende pelo telefone do perfil.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'eletro-company'), 'Loja de material elétrico que resolve rápido: o cliente encontra o item certo, tira dúvidas pelo WhatsApp e recebe orientação clara. Destacar a linha completa (cabos, disjuntores, quadros, iluminação, ventilação) e a entrega em Londrina e região.', 'Direto e prático, de balcão. Frases curtas; termos técnicos só quando ajudam o eletricista e quem constrói.', 'voce', 'nenhum', 'Equipe Eletro Company', 'material elétrico, iluminação, disjuntores, cabos, quadros, chuveiros, pedido pelo WhatsApp, entrega em Londrina e região', 'preço, desconto, estoque garantido, prazo de entrega, marca sem confirmação, instruções de instalação', 'Olá, {nome}! Obrigado pela avaliação. Que bom que encontrou o que precisava na Eletro Company. Para cabos, disjuntores, iluminação e o que mais a sua obra pedir, conte com a gente em Londrina.', 'Obra ou reforma em Londrina? Na Eletro Company você encontra cabos, disjuntores, quadros e iluminação em um só lugar. Chame no WhatsApp e tire suas dúvidas com a equipe.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'garagem-3'), 'Revendedora de seminovos que passa confiança: carros bem apresentados, transparência e atendimento direto. Destacar multimarcas, compra, troca e documentação.', 'Confiante e direto, sem pressão de venda. Linguagem de quem entende de carro e respeita o cliente.', 'voce', 'nenhum', 'Equipe Garagem 3', 'seminovos, multimarcas, troca, compra de usados, transferência e documentação, Av. Juscelino Kubitschek, Londrina', 'preço, parcelas, financiamento, aprovação de crédito, estado ou procedência garantidos, promoção, estoque', 'Olá, {nome}! Obrigado pela avaliação e pela confiança na Garagem 3. Seguimos à disposição em Londrina para a compra, a troca ou a avaliação do seu veículo.', 'Procurando um seminovo em Londrina? A Garagem 3 trabalha com veículos de várias marcas e também faz a troca do seu carro, mediante avaliação. Venha conhecer ou chame no WhatsApp.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'brava-motors'), 'Oficina mecânica focada em diagnóstico correto: scanner, injeção eletrônica, revisão e arrefecimento. Transmitir competência técnica e transparência.', 'Técnico e honesto. Explica o problema em palavras simples, sem assustar.', 'voce', 'nenhum', 'Equipe Brava Motors', 'revisão preventiva e corretiva, diagnóstico com scanner, injeção eletrônica, arrefecimento, Londrina', 'preço, prazo de conserto, garantia, criticar outras oficinas, diagnóstico sem o carro na oficina', 'Olá, {nome}! Obrigado pela avaliação. Na Brava Motors, em Londrina, cuidamos da revisão, do diagnóstico com scanner e da manutenção do seu carro. Conte com a gente sempre que precisar.', 'Luz no painel acesa? Na Brava Motors, em Londrina, o diagnóstico com scanner ajuda a encontrar a causa do problema antes de qualquer reparo. Chame no WhatsApp e agende.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'zero-a-sete'), 'Estética e proteção automotiva: insulfilm, películas, PPF, vitrificação, polimento e detalhamento. O carro sai protegido e bonito, com acabamento caprichado.', 'Caprichoso e animado sem exagero; fala de acabamento e cuidado com o carro.', 'voce', 'nenhum', 'Equipe Zero a Sete', 'insulfilm, película nano cerâmica, PPF, vitrificação, polimento, detalhamento, Cambé e Londrina', 'preço, prazo de aplicação, garantia de durabilidade, afirmar que a película é legal ou dentro da norma, comparação com concorrentes', 'Olá, {nome}! Obrigado pela avaliação. Ficamos felizes que tenha gostado do resultado na Zero a Sete, em Cambé. Para insulfilm, polimento ou proteção da pintura, estamos à disposição.', 'Quer cuidar do visual e da proteção do seu carro? Na Zero a Sete, em Cambé, fazemos insulfilm, polimento, vitrificação e detalhamento automotivo. Chame no WhatsApp.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'bilumix'), 'Concreteira de Cambé que entrega concreto e argamassa com planejamento. Falar com construtoras, engenheiros e quem constrói.', 'Objetivo e profissional, vocabulário de obra. Sem enfeite.', 'voce', 'nenhum', 'Equipe Bilumix', 'concreto usinado, argamassa, lajes, fundações, pisos, bombeamento, entrega, Cambé', 'preço por m³, prazo de entrega, resistência garantida sem projeto, regiões atendidas (a área ainda será definida pelo dono)', 'Olá, {nome}! Obrigado pela avaliação. A Bilumix, em Cambé, fornece concreto usinado e argamassa para obras. Para a sua próxima obra, é só falar com a nossa equipe.', 'Obra em andamento? A Bilumix, em Cambé, fornece concreto usinado e argamassa para lajes, fundações e pisos. Informe o volume e o tipo de obra e fale com a nossa equipe.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'kellin-obana'), 'Consultoria de consórcio imobiliário com orientação clara: a pessoa entende como funciona antes de decidir. Educar, não prometer.', 'Didático e transparente, calmo. Explica termos como carta de crédito, lance e contemplação.', 'voce', 'nenhum', 'Kellin Obana', 'consórcio imobiliário, carta de crédito, lance, simulação, planejamento, Londrina', 'promessa de contemplação, prazo, rentabilidade, valor de parcela, afirmar que consórcio é melhor que financiamento', 'Olá, {nome}! Obrigada pela avaliação e pela confiança. Fico à disposição em Londrina para tirar dúvidas sobre consórcio imobiliário e fazer a sua simulação.', 'Planejar a compra do imóvel começa por entender as opções. Em Londrina, explico como funciona o consórcio imobiliário, a carta de crédito e o lance, sem pressa. Fale comigo pelo WhatsApp.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'aline-ceccotti'), 'Clínica de estética avançada em Cambé com atendimento individual e tecnologia. Informar com responsabilidade: cada procedimento depende de avaliação.', 'Cuidadoso, acolhedor e discreto: confiança sem promessa.', 'voce', 'nenhum', 'Aline Ceccotti Estética Avançada', 'limpeza de pele, peeling, microagulhamento, depilação a laser, avaliação individual, Cambé e Londrina', 'promessa de resultado, antes e depois, dado de saúde, preço, linguagem de prescrição médica', 'Olá, {nome}! Obrigada pela avaliação e pela confiança. Foi um prazer cuidar de você na Aline Ceccotti Estética Avançada, em Cambé. Seguimos à disposição para a sua próxima avaliação.', 'Cada pele tem a sua necessidade. Na Aline Ceccotti Estética Avançada, em Cambé, o atendimento começa com uma avaliação individual. Agende pelo WhatsApp.', 'automatica', false) on conflict do nothing;
insert into public.diretrizes (cliente_id, ideia_principal, tom, tratamento, emojis, assinatura, usar, evitar, exemplo_resposta, exemplo_postagem, aprovacao, revisado) values ((select id from public.clientes where slug = 'marktiva'), 'Agência de marketing digital para negócios locais, com estúdio na Gleba Palhano. Mostrar na prática: bons conteúdos, boas fotos e o trabalho com clientes reais.', 'Criativo, direto e profissional; fala de negócio para dono de negócio.', 'voce', 'nenhum', 'Equipe Marktiva', 'marketing digital, tráfego pago, vídeo, fotografia, redes sociais, criação de site, estúdio na Gleba Palhano, Londrina', 'promessa de resultado, números de venda sem comprovação, preço, comparação com outras agências', 'Olá, {nome}! Obrigado pela avaliação e pela confiança na Marktiva. Seguimos juntos para fazer o seu negócio ser visto em Londrina.', 'O seu negócio aparece quando as pessoas procuram? Na Marktiva, em Londrina, cuidamos de marketing digital, tráfego pago, vídeos e redes sociais. Fale com a nossa equipe.', 'automatica', false) on conflict do nothing;
